import { facetPaddingBottom, facetPaddingLeft, facetPaddingRight, facetPaddingTop, } from './defaults';
export function getFacetLayout(facetStyle, facetColumn, facetVColumn, axisTextColor) {
    let layoutPair;
    const groupby = facetColumn;
    const plotPadding = {
        x: 0,
        y: 0,
    };
    let facetPadding;
    switch (facetStyle) {
        case 'cross': {
            const props = {
                axisTextColor,
                colRowTitles: true,
                groupbyX: groupby,
                groupbyY: facetVColumn,
            };
            layoutPair = {
                layoutType: 'Cross',
                props,
            };
            facetPadding = {
                bottom: facetPaddingBottom,
                left: facetPaddingLeft,
                top: 0,
            };
            plotPadding.y = facetPaddingTop;
            plotPadding.x = facetPaddingRight;
            break;
        }
        case 'wrap':
        default: {
            const props = {
                axisTextColor,
                cellTitles: true,
                groupby,
            };
            layoutPair = {
                layoutType: 'Wrap',
                props,
            };
            facetPadding =
                {
                    bottom: facetPaddingBottom,
                    left: facetPaddingLeft,
                    top: facetPaddingTop,
                };
            break;
        }
    }
    const facetLayout = {
        facetPadding,
        plotPadding,
    };
    return {
        layoutPair,
        facetLayout,
    };
}
