import { vec3, vec4 } from "gl-matrix";
import { Constants } from "./constants.js";
import { HighlightMode, LogLevel, RenderMode, StereoMode, Theme } from "./main.js";
import { AngleHelper } from "./helpers/angle.js";
export class Config {
    constructor(core) {
        this.reset();
    }
    reset() {
        this.isDebugVisible = false;
        this.logLevel = LogLevel.warn;
        this.shaderPath = "shaders";
        this.fontPath = "fonts";
        this.modelDistance = 0.5;
        this.modelSize = 0.25;
        this.stereoMode = StereoMode.none;
        this.ipd = 0.06;
        this.screenDistance = 0.5;
        this.fov = AngleHelper.degreesToRadians(30);
        this.nearPlane = 0.01;
        this.farPlane = 100;
        this.pickWidth = 512;
        this.pickHeight = 512;
        this.pickHoldDelay = 1000;
        this.pickSelectDelay = 100;
        this.resizeMinimumDelay = 250;
        this.rotationSmoothing = 0.02;
        this.positionSmoothing = 0.02;
        this.focusSmoothing = 0.01;
        this.scaleSmoothing = 0.02;
        this.mouseWheelZoomScale = -0.002;
        this.mouseWheelRotationScale = -0.002;
        this.dragToleranceSquared = 100;
        this.manipulatorMinRelativeDistanceSquared = 100;
        this.isMultiTouchEnabled = true;
        this.isMultiTouchZoomEnabled = true;
        this.isMultiTouchTwistEnabled = true;
        this.isMultiTouchRotateEnabled = true;
        this.isMultiTouchTranslateEnabled = true;
        this.multiTouchZoomScale = 1;
        this.cameraMinDistance = 0.1;
        this.cameraMaxDistance = 10;
        this.xrControllerRayColor = vec3.fromValues(0.5, 0.5, 0.5);
        this.xrControllerProfile = "windows-mixed-reality";
        this.xrControllerHandedness = "right";
        this.paletteColor = new Uint8Array([0x80, 0x80, 0x80, 0]);
        this.textColor = vec3.create();
        this.textHoverColor = vec3.create();
        this.textBorderColor = vec3.create();
        this.textBorderWidth = 0x18 / 0xff;
        this.identityRotation = Constants.VECTOR3_UNITY;
        this.axesTextLabelMaxGlyphs = 32;
        this.axesTextColor = vec3.create();
        this.axesTextBorderColor = vec3.create();
        this.axesTextHoverColor = vec3.create();
        this.axesTextLabelMajorSize = 0.03;
        this.axesTextLabelMinorSize = 0.02;
        this.axesTextTitleMaxGlyphs = 127;
        this.axesTextTitleSize = 0.05;
        this.axesTextHeadingMaxGlyphs = 128;
        this.axesTextHeadingSize = 0.075;
        this.axesTextTitleLineHeight = 1.5;
        this.axesTextHeadingLineHeight = 1.5;
        this.axesTextLabelLineHeight = 1.5;
        this.axesGridMajorThickness = 0.0002;
        this.axesGridMinorThickness = 0.0001;
        this.axesGridZeroThickness = 0.002;
        this.axesGridPickDivisionHeight = 0.025;
        this.axesGridBackgroundColor = vec3.create();
        this.axesGridHighlightColor = vec3.create();
        this.axesGridMinorColor = vec3.create();
        this.axesGridMajorColor = vec3.create();
        this.axesGridZeroColor = vec3.create();
        this.axesGridDefaultDivisions = 10;
        this.keyTitleMaxGlyphs = 64;
        this.keyLabelMaxGlyphs = 64;
        this.selectionColor = vec3.create();
        this.hoverColor = vec3.create();
        this.activeColor = vec3.create();
        this.highlightMode = HighlightMode.color;
        this.lassoThickness = 4;
        this.lassoDashWidth = 2;
        this.lassoColor = vec3.create();
        this.minCubifiedTreeMapSlice = 0.01;
        this.sdfBuffer = 0xc0;
        this.sdfBorder = 0x0;
        this.forceDirectIsEnabled = false;
        this.forceDirectAttraction = 1;
        this.forceDirectRepulsion = 1;
        this.forceDirectGravity = 1;
        this.forceDirectInterval = 0.1;
        this.forceDirectMaxDistance = 0.1;
        this.forceDirectTheta = 1;
        this.forceDirectIterationsPerLayout = 1;
        this.forceDirectEdgeWeightPower = 1;
        this.forceDirectLockX = false;
        this.forceDirectLockY = false;
        this.forceDirectLockZ = false;
        this.transitionDuration = 400;
        this.transitionStaggering = 100;
        this.transitionView = true;
        this.isTransitionPickingEnabled = false;
        this.backgroundColor = vec4.create();
        this.theme = Theme.light;
        this.renderMode = RenderMode.color;
        this.tilesX = 1;
        this.tilesY = 1;
        this.tileOffsetX = 0;
        this.tileOffsetY = 0;
    }
    get theme() { return this._theme; }
    set theme(value) {
        if (this._theme != value) {
            this._theme = value;
            switch (value) {
                case Theme.dark:
                    vec4.set(this.backgroundColor, 0, 0, 0, 1);
                    vec3.set(this.textColor, 0.9, 0.9, 0.9);
                    vec3.set(this.textHoverColor, 1, 1, 1);
                    vec3.set(this.textBorderColor, 0, 0, 0);
                    vec3.set(this.axesTextColor, 0.9, 0.9, 0.9);
                    vec3.set(this.axesTextBorderColor, 0, 0, 0);
                    vec3.set(this.axesTextHoverColor, 1, 1, 1);
                    vec3.set(this.axesGridBackgroundColor, 0.02, 0.02, 0.02);
                    vec3.set(this.axesGridHighlightColor, 0.04, 0.04, 0.04);
                    vec3.set(this.axesGridMinorColor, 0.05, 0.05, 0.05);
                    vec3.set(this.axesGridMajorColor, 0.1, 0.1, 0.1);
                    vec3.set(this.axesGridZeroColor, 0.05, 0.1, 0.1);
                    vec3.set(this.selectionColor, 1, 1, 0);
                    vec3.set(this.hoverColor, 1, 0, 1);
                    vec3.set(this.activeColor, 0, 1, 1);
                    vec3.set(this.lassoColor, 0.9, 0.9, 0.9);
                    break;
                case Theme.light:
                    vec4.set(this.backgroundColor, 1, 1, 1, 1);
                    vec3.set(this.textColor, 0, 0, 0);
                    vec3.set(this.textHoverColor, 0.1, 0.1, 0.1);
                    vec3.set(this.textBorderColor, 1, 1, 1);
                    vec3.set(this.axesTextColor, 0, 0, 0);
                    vec3.set(this.axesTextBorderColor, 1, 1, 1);
                    vec3.set(this.axesTextHoverColor, 0.1, 0.1, 0.1);
                    vec3.set(this.axesGridBackgroundColor, 1, 1, 1);
                    vec3.set(this.axesGridHighlightColor, 0.925, 0.925, 0.925);
                    vec3.set(this.axesGridMinorColor, 0.9, 0.9, 0.9);
                    vec3.set(this.axesGridMajorColor, 0.8, 0.8, 0.8);
                    vec3.set(this.axesGridZeroColor, 0.7, 0.9, 0.9);
                    vec3.set(this.selectionColor, 1, 1, 0);
                    vec3.set(this.hoverColor, 1, 0, 1);
                    vec3.set(this.activeColor, 0, 1, 1);
                    vec3.set(this.lassoColor, 0.1, 0.1, 0.1);
                    break;
            }
            if (this.themeChangedCallback) {
                this.themeChangedCallback(this._theme);
            }
        }
    }
}
