import { mat3, vec2, vec3, vec4 } from "gl-matrix";
import { Constants } from "../constants.js";
import { PositionNormalTextureVertex, PositionTextureVertex, PositionVertex } from "../vertex.js";
export class Quad {
    static positions(transform) {
        const positions = new Float32Array(12);
        const position = vec3.create();
        for (let i = 0; i < 4; i++) {
            vec3.set(position, this.POSITIONS[i * 3], this.POSITIONS[i * 3 + 1], this.POSITIONS[i * 3 + 2]);
            vec3.transformMat4(position, position, transform);
            positions[i * 3] = position[0];
            positions[i * 3 + 1] = position[1];
            positions[i * 3 + 2] = position[2];
        }
        return positions;
    }
    static textured(transform, texTransform = Constants.MAT4_IDENTITY) {
        const positions = this.positions(transform);
        const texCoords = this.TEX_COORDS;
        const vertices = new ArrayBuffer(PositionTextureVertex.SIZE_BYTES * positions.length / 3);
        const verticesView = new DataView(vertices);
        const position = vec3.create();
        const texCoord = vec2.create();
        for (let i = 0; i < positions.length / PositionVertex.SIZE; i++) {
            vec3.set(position, positions[i * PositionVertex.SIZE], positions[i * PositionVertex.SIZE + 1], positions[i * PositionVertex.SIZE + 2]);
            vec2.set(texCoord, texCoords[i * 2], texCoords[i * 2 + 1]);
            vec2.transformMat4(texCoord, texCoord, texTransform);
            PositionTextureVertex.setPosition(verticesView, i, position);
            PositionTextureVertex.setTexCoord(verticesView, i, texCoord);
        }
        return verticesView;
    }
    static normalTextured(transform, texTransform = Constants.MAT4_IDENTITY) {
        const positions = this.positions(transform);
        const texCoords = this.TEX_COORDS;
        const vertices = new ArrayBuffer(PositionNormalTextureVertex.SIZE_BYTES * positions.length / 3);
        const verticesView = new DataView(vertices);
        const position = vec3.create();
        const texCoord = vec2.create();
        const normal3 = vec3.create();
        const normal4 = vec4.create();
        for (let i = 0; i < positions.length / PositionVertex.SIZE; i++) {
            vec3.set(position, positions[i * PositionVertex.SIZE], positions[i * PositionVertex.SIZE + 1], positions[i * PositionVertex.SIZE + 2]);
            vec2.set(texCoord, texCoords[i * 2], texCoords[i * 2 + 1]);
            vec2.transformMat4(texCoord, texCoord, texTransform);
            PositionNormalTextureVertex.setPosition(verticesView, i, position);
            vec4.set(normal4, 0.0, 0.0, 1.0, 0.0);
            vec4.transformMat4(normal4, normal4, transform);
            vec3.set(normal3, normal4[0], normal4[1], normal4[2]);
            vec3.normalize(normal3, normal3);
            PositionNormalTextureVertex.setNormal(verticesView, i, normal3);
            PositionNormalTextureVertex.setTexCoord(verticesView, i, texCoord);
        }
        return verticesView;
    }
}
Quad.FACE_NORMALS = [
    vec3.fromValues(0, 0, 1),
    vec3.fromValues(0, 0, -1)
];
Quad.FACE_ROTATIONS = [
    mat3.fromValues(1, 0, 0, 0, 1, 0, 0, 0, 1),
    mat3.fromValues(1, 0, 0, 0, -1, 0, 0, 0, -1)
];
Quad.EDGE_POSITIONS = [
    vec3.fromValues(0, 0.5, 0),
    vec3.fromValues(0.5, 0, 0),
    vec3.fromValues(0, -0.5, 0),
    vec3.fromValues(-0.5, 0, 0)
];
Quad.EDGE_NORMALS = [
    vec3.fromValues(0, 1, 0),
    vec3.fromValues(1, 0, 0),
    vec3.fromValues(0, -1, 0),
    vec3.fromValues(-1, 0, 0)
];
Quad.EDGE_POSITIVES = [
    vec3.fromValues(1, 0, 0),
    vec3.fromValues(0, 1, 0),
    vec3.fromValues(1, 0, 0),
    vec3.fromValues(0, 1, 0)
];
Quad.EDGE_FORWARDS = [
    vec3.fromValues(0, 0, -1),
    vec3.fromValues(0, 0, 1),
    vec3.fromValues(0, 0, 1),
    vec3.fromValues(0, 0, -1)
];
Quad.AXIS_EDGES = [
    [0, 2],
    [1, 3]
];
Quad.POSITIONS = new Float32Array([
    -0.5, 0.5, 0,
    0.5, 0.5, 0,
    -0.5, -0.5, 0,
    0.5, -0.5, 0
]);
Quad.INDICES = new Uint16Array([0, 2, 1, 1, 2, 3]);
Quad.TEX_COORDS = new Float32Array([0, 1, 1, 1, 0, 0, 1, 0]);
export class Grid {
    static positions(cols, rows, transform) {
        const vertices = new Float32Array((cols + 1) * (rows + 1) * PositionVertex.SIZE);
        const position = vec3.create();
        let index = 0;
        for (let row = 0; row <= rows; row++) {
            for (let col = 0; col <= cols; col++) {
                vec3.set(position, col / cols - 0.5, 0.5 - row / rows, 0);
                vec3.transformMat4(position, position, transform);
                PositionVertex.setPosition(vertices, index++, position);
            }
        }
        return vertices;
    }
    static indices(cols, rows) {
        const indices = new Uint16Array(cols * rows * 6);
        let index = 0;
        for (let row = 0; row < rows; row++) {
            for (let col = 0; col < cols; col++) {
                indices[index++] = col + row * (cols + 1);
                indices[index++] = col + (row + 1) * (cols + 1);
                indices[index++] = col + row * (cols + 1) + 1;
                indices[index++] = col + row * (cols + 1) + 1;
                indices[index++] = col + (row + 1) * (cols + 1);
                indices[index++] = col + (row + 1) * (cols + 1) + 1;
            }
        }
        return indices;
    }
    static textured(cols, rows, transform, texTransform = Constants.MAT4_IDENTITY) {
        const positions = this.positions(cols, rows, transform);
        const texCoords = this._texCoords(cols, rows, texTransform);
        const vertices = new ArrayBuffer(PositionTextureVertex.SIZE_BYTES * positions.length / 3);
        const verticesView = new DataView(vertices);
        const position = vec3.create();
        const texCoord = vec2.create();
        let index = 0;
        for (let i = 0; i < positions.length / PositionVertex.SIZE; i++) {
            vec3.set(position, positions[i * PositionVertex.SIZE], positions[i * PositionVertex.SIZE + 1], positions[i * PositionVertex.SIZE + 2]);
            vec2.set(texCoord, texCoords[i * 2], texCoords[i * 2 + 1]);
            PositionTextureVertex.setPosition(verticesView, index, position);
            PositionTextureVertex.setTexCoord(verticesView, index++, texCoord);
        }
        return verticesView;
    }
    static normalTextured(cols, rows, transform, texTransform = Constants.MAT4_IDENTITY) {
        const positions = this.positions(cols, rows, transform);
        const texCoords = this._texCoords(cols, rows, texTransform);
        const vertices = new ArrayBuffer(PositionNormalTextureVertex.SIZE_BYTES * positions.length / 3);
        const verticesView = new DataView(vertices);
        const position = vec3.create();
        const texCoord = vec2.create();
        let index = 0;
        for (let i = 0; i < positions.length / PositionVertex.SIZE; i++) {
            vec3.set(position, positions[i * PositionVertex.SIZE], positions[i * PositionVertex.SIZE + 1], positions[i * PositionVertex.SIZE + 2]);
            vec2.set(texCoord, texCoords[i * 2], texCoords[i * 2 + 1]);
            PositionNormalTextureVertex.setPosition(verticesView, index, position);
            PositionNormalTextureVertex.setNormal(verticesView, index, Constants.VECTOR3_UNITZ);
            PositionNormalTextureVertex.setTexCoord(verticesView, index++, texCoord);
        }
        return verticesView;
    }
    static _texCoords(cols, rows, transform) {
        const texCoords = new Float32Array((cols + 1) * (rows + 1) * 2);
        const texCoord = vec2.create();
        let index = 0;
        for (let row = 0; row <= rows; row++) {
            for (let col = 0; col <= cols; col++) {
                vec2.set(texCoord, col / cols, 1 - row / rows);
                vec2.transformMat4(texCoord, texCoord, transform);
                texCoords[index++] = texCoord[0];
                texCoords[index++] = texCoord[1];
            }
        }
        return texCoords;
    }
}
