export class AxesVisualBase {
    get isInitialized() { return this._isInitialized; }
    get axes() { return this._axes; }
    constructor(core) {
        this._core = core;
        this.isVisible = true;
    }
    initializeContext(gl) {
        this._gl = gl;
    }
    update(elapsedTime) { }
    render(elapsedTime, xrFrame) {
        if (this.isInitialized) {
            this._renderGrid();
            this._renderText();
        }
    }
    _renderGrid() { }
    _renderText() { }
}
