import { vec2, vec3 } from "gl-matrix";
import { Constants } from "../constants.js";
import { AngleHelper } from "../helpers/angle.js";
import { PositionNormalTextureVertex, PositionTextureVertex, PositionVertex } from "../vertex.js";
export class Sphere {
    constructor(core) { }
    positions(slices, stacks, transform) {
        const vertices = new Float32Array((slices + 1) * (stacks + 1) * PositionVertex.SIZE);
        const position = vec3.create();
        let index = 0;
        for (let stack = 0; stack <= stacks; stack++) {
            const latitude = 90 - 180 * stack / stacks;
            for (let slice = 0; slice <= slices; slice++) {
                const longitude = 360 * slice / slices - 180;
                AngleHelper.sphericalToCartesian(1, longitude, latitude, position);
                vec3.transformMat4(position, position, transform);
                PositionVertex.setPosition(vertices, index++, position);
            }
        }
        return vertices;
    }
    indices(slices, stacks) {
        const indices = new Uint16Array(slices * stacks * 6);
        let index = 0;
        for (let stack = 0; stack < stacks; stack++) {
            const top = stack * (slices + 1);
            const bottom = (stack + 1) * (slices + 1);
            for (let slice = 0; slice < slices; slice++) {
                if (stack != 0) {
                    indices[index++] = top + slice;
                    indices[index++] = bottom + slice;
                    indices[index++] = top + slice + 1;
                }
                if (stack != stacks - 1) {
                    indices[index++] = top + slice + 1;
                    indices[index++] = bottom + slice;
                    indices[index++] = bottom + slice + 1;
                }
            }
        }
        return indices;
    }
    textured(slices, stacks, transform, texTransform = Constants.MAT4_IDENTITY) {
        const positions = this.positions(slices, stacks, transform);
        const texCoords = this._texCoords(slices, stacks, texTransform);
        const vertices = new ArrayBuffer(PositionTextureVertex.SIZE_BYTES * positions.length / 3);
        const verticesView = new DataView(vertices);
        const position = vec3.create();
        const texCoord = vec2.create();
        for (let i = 0; i < positions.length / PositionVertex.SIZE; i++) {
            vec3.set(position, positions[i * PositionVertex.SIZE], positions[i * PositionVertex.SIZE + 1], positions[i * PositionVertex.SIZE + 2]);
            vec2.set(texCoord, texCoords[i * 2], texCoords[i * 2 + 1]);
            PositionTextureVertex.setPosition(verticesView, i, position);
            PositionTextureVertex.setTexCoord(verticesView, i, texCoord);
        }
        return verticesView;
    }
    normalTextured(slices, stacks, transform, texTransform = Constants.MAT4_IDENTITY) {
        const positions = this.positions(slices, stacks, transform);
        const texCoords = this._texCoords(slices, stacks, texTransform);
        const vertices = new ArrayBuffer(PositionNormalTextureVertex.SIZE_BYTES * positions.length / 3);
        const verticesView = new DataView(vertices);
        const position = vec3.create();
        const texCoord = vec2.create();
        const normal = vec3.create();
        for (let i = 0; i < positions.length / PositionVertex.SIZE; i++) {
            vec3.set(position, positions[i * PositionVertex.SIZE], positions[i * PositionVertex.SIZE + 1], positions[i * PositionVertex.SIZE + 2]);
            vec2.set(texCoord, texCoords[i * 2], texCoords[i * 2 + 1]);
            PositionNormalTextureVertex.setPosition(verticesView, i, position);
            PositionNormalTextureVertex.setTexCoord(verticesView, i, texCoord);
            vec3.set(normal, position[0] - transform[12], position[1] - transform[13], position[2] - transform[14]);
            vec3.normalize(normal, normal);
            PositionNormalTextureVertex.setNormal(verticesView, i, normal);
        }
        return verticesView;
    }
    _texCoords(slices, stacks, transform) {
        const texCoords = new Float32Array((slices + 1) * (stacks + 1) * 2);
        const texCoord = vec2.create();
        let index = 0;
        for (let stack = 0; stack <= stacks; stack++) {
            for (let slice = 0; slice <= slices; slice++) {
                vec2.set(texCoord, slice / slices, stack / stacks);
                vec2.transformMat4(texCoord, texCoord, transform);
                texCoords[index++] = texCoord[0];
                texCoords[index++] = texCoord[1];
            }
        }
        return texCoords;
    }
}
