import { LogLevel } from "../main.js";
export class FacetHelper {
    constructor(core) {
        this._core = core;
    }
    split1d(ids, facetsX, valuesX, orderedIds, facetIds, offsets, counts) {
        this.split3d(ids, facetsX, undefined, undefined, valuesX, null, null, orderedIds, facetIds, offsets, counts);
    }
    split2d(ids, facetsX, facetsY, valuesX, valuesY, orderedIds, facetIds, offsets, counts) {
        this.split3d(ids, facetsX, facetsY, undefined, valuesX, valuesY, null, orderedIds, facetIds, offsets, counts);
    }
    split3d(ids, facetsX, facetsY, facetsZ, valuesX, valuesY, valuesZ, orderedIds, facetIds, offsets, counts) {
        if (valuesX && facetIds.length != valuesX.length) {
            this._core.log.write(LogLevel.warn, "facet helper split1d facetIds should be same length as facetValuesX");
        }
        if (valuesY && facetIds.length != valuesY.length) {
            this._core.log.write(LogLevel.warn, "facet helper split1d facetIds should be same length as facetValuesY");
        }
        if (valuesZ && facetIds.length != valuesY.length) {
            this._core.log.write(LogLevel.warn, "facet helper split1d facetIds should be same length as facetValuesY");
        }
        const start = window.performance.now();
        if (facetsX === undefined)
            facetsX = 1;
        if (facetsY === undefined)
            facetsY = 1;
        if (facetsZ === undefined)
            facetsZ = 1;
        const maxFacetId = facetsX * facetsY * facetsZ - 1;
        for (let i = 0; i < ids.length; i++) {
            const id = ids[i];
            const valueX = valuesX ? valuesX[id] : 0;
            const valueY = valuesY ? valuesY[id] : 0;
            const valueZ = valuesZ ? valuesZ[id] : 0;
            const facetId = valueX + valueY * facetsX + valueZ * facetsX * facetsZ;
            facetIds[id] = facetId;
            if (facetId > maxFacetId) {
                this._core.log.write(LogLevel.warn, "facet overflow");
            }
            counts[facetId]++;
        }
        let offset = 0;
        for (let i = 0; i < offsets.length; i++) {
            const count = counts[i];
            offsets[i] = offset;
            offset += count;
        }
        const tempOffsets = new Uint32Array(offsets);
        for (let i = 0; i < ids.length; i++) {
            const id = ids[i];
            const facetId = facetIds[id];
            offset = tempOffsets[facetId]++;
            orderedIds[offset] = id;
        }
        this._core.log.write(LogLevel.info, `facet split ${Math.round(window.performance.now() - start)}ms`);
    }
    wrap1d(ids, values, columns, coordsX, coordsY) {
        const start = window.performance.now();
        let rows = 0;
        for (let i = 0; i < ids.length; i++) {
            const id = ids[i];
            const value = values[id];
            coordsX[id] = value % columns;
            const row = Math.floor(value / columns);
            coordsY[id] = row;
            rows = Math.max(row, rows);
        }
        this._core.log.write(LogLevel.info, `facet wrap ${Math.round(window.performance.now() - start)}ms`);
        return rows + 1;
    }
}
