export class AtlasBase {
    get imageData() { return this._imageData; }
    set imageData(value) {
        if (this._imageData != value) {
            this._imageData = value;
            this._changed = true;
        }
    }
    constructor() {
        this._imageData = null;
    }
    copyFrom(atlas) {
        if (atlas.imageData) {
            this._imageData = atlas.imageData;
            this._changed = true;
        }
        else {
            this.imageData = null;
        }
    }
    update() { }
}
export class Atlas extends AtlasBase {
}
