import { LogLevel } from "../main.js";
export class CsvHelper {
    constructor(core) {
        this.QUOTE = '"';
        this.DELIMETER = ',';
        this.LINE_BREAKS = ['\n', '\r'];
        this._core = core;
    }
    readline(text, row) {
        return this.read(text, row, 1)[0];
    }
    read(text, firstRow = 0, maxRows = Number.MAX_VALUE) {
        const start = window.performance.now();
        const rows = [];
        let rowBuffer = [];
        let row = 0;
        let columnBuffer = "";
        let quoted = false;
        for (let i = 0; i < text.length; i++) {
            const char = text.charAt(i);
            if (char == this.QUOTE) {
                if (text.charAt(i + 1) == this.QUOTE) {
                    i++;
                    columnBuffer += this.QUOTE;
                }
                else {
                    quoted = !quoted;
                }
            }
            else {
                if (quoted) {
                    columnBuffer += char;
                }
                else {
                    if (char == this.DELIMETER) {
                        rowBuffer.push(columnBuffer);
                        columnBuffer = "";
                    }
                    else if (this.LINE_BREAKS.indexOf(char) > -1) {
                        rowBuffer.push(columnBuffer);
                        columnBuffer = "";
                        while (this.LINE_BREAKS.indexOf(text.charAt(i + 1)) > -1) {
                            i++;
                        }
                        if (row++ >= firstRow) {
                            rows.push(rowBuffer);
                        }
                        rowBuffer = [];
                        if (rows.length == maxRows) {
                            break;
                        }
                    }
                    else {
                        columnBuffer += char;
                    }
                }
            }
        }
        if (columnBuffer != "") {
            rowBuffer.push(columnBuffer);
        }
        if (rowBuffer.length > 0) {
            rows.push(rowBuffer);
        }
        if (maxRows > 1) {
            this._core.log.write(LogLevel.info, `csv ${rows.length} rows ${Math.round(window.performance.now() - start)}ms`);
        }
        return rows;
    }
    writeLine(data) {
        let text = "";
        for (let i = 0; i < data.length; i++) {
            let column = data[i];
            if (column) {
                const quotes = column.indexOf(this.DELIMETER) > -1 || column.indexOf(this.QUOTE) > -1;
                column = column.replace(/"/g, '""');
                if (quotes) {
                    column = `${this.QUOTE}${column}${this.QUOTE}`;
                }
            }
            text += column;
            if (i < data.length - 1) {
                text += this.DELIMETER;
            }
        }
        return text;
    }
    writeAsJavaScriptArray(headings, data) {
        let text = "[[";
        for (let column of headings) {
            text += `"${column}",`;
        }
        text = text.slice(0, -1);
        text += "]\n";
        let row;
        for (let i = 0; i < data.length; i++) {
            const line = data[i];
            row = "[";
            for (let j = 0; j < line.length; j++) {
                const column = line[j];
                row += `"${column.replace(/"/g, '\\"')}",`;
            }
            row = row.slice(0, -1);
            row += "],\n";
            text += row;
        }
        text += "];";
        return text;
    }
}
