export class ArrayHelper {
    static minIndex(orderedValues, offset, length, value) {
        let index = ArrayHelper.binarySearch(orderedValues, offset, length, value);
        if (index < 0) {
            index = ~index;
            index = Math.max(0, index);
        }
        else {
            while (index > 0 && orderedValues[index - 1] == value) {
                index--;
            }
        }
        return index;
    }
    static maxIndex(orderedValues, offset, length, value) {
        let index = ArrayHelper.binarySearch(orderedValues, offset, length, value);
        if (index < 0) {
            index = ~index - 1;
        }
        else {
            while (index < length - 1 && orderedValues[index + 1] == value) {
                index++;
            }
            index = Math.min(length, index);
        }
        return index;
    }
    static binarySearch(array, index, length, value) {
        let low = index;
        let high = index + length - 1;
        while (low <= high) {
            const mid = low + ((high - low) >> 1);
            if (array[mid] == value) {
                return mid;
            }
            if (array[mid] <= value) {
                low = mid + 1;
            }
            else {
                high = mid - 1;
            }
        }
        return ~low;
    }
}
