import { LogLevel } from "../main.js";
export class LineHelper {
    constructor(core) {
        this._core = core;
    }
    connect(orderedIds, series, toIds, offset = 0, count = orderedIds.length) {
        const start = window.performance.now();
        const lines = new Set();
        const lookup = {};
        for (let i = offset; i < count; i++) {
            const id = orderedIds[i + offset];
            const value = series[id];
            const fromId = lookup[value];
            if (fromId != null) {
                toIds[fromId] = id;
                lines.add(value);
            }
            lookup[value] = id;
            toIds[id] = id;
        }
        this._core.log.write(LogLevel.info, `${lines.size} lines connected ${Math.round(window.performance.now() - start)}ms`);
        return lines.size;
    }
}
