import { LogLevel } from "../main.js";
import { ColumnType } from "../tables/table.js";
export class TableHelper {
    constructor(core) {
        this._core = core;
    }
    compatibleTypes(data, firstRow = 0, maxRows = Number.MAX_VALUE) {
        const start = window.performance.now();
        const types = [];
        const integers = [];
        let values = data[firstRow];
        let parsedFloat, parsedDate;
        for (let i = 0; i < values.length; i++) {
            const value = values[i];
            parsedFloat = Number(value);
            parsedDate = Date.parse(value);
            let integer = false;
            let type;
            if (!isNaN(parsedFloat)) {
                type = ColumnType.float;
                integer = Number.isSafeInteger(parsedFloat);
            }
            else if (!isNaN(parsedDate)) {
                type = ColumnType.date;
            }
            else {
                type = ColumnType.string;
            }
            types.push(type);
            integers.push(integer);
        }
        for (let i = firstRow + 1; i < Math.min(data.length, firstRow + maxRows); i++) {
            values = data[i];
            for (let j = 0; j < values.length; j++) {
                if (types[j] != ColumnType.string) {
                    const value = values[j];
                    parsedFloat = Number(value);
                    if (types[j] == ColumnType.float) {
                        if (isNaN(parsedFloat)) {
                            types[j] = ColumnType.string;
                            integers[j] = false;
                        }
                        else if (integers[j]) {
                            integers[j] = Number.isSafeInteger(parsedFloat);
                        }
                    }
                    else if (types[j] == ColumnType.date) {
                        parsedDate = Date.parse(value);
                        if (isNaN(parsedDate)) {
                            types[j] = ColumnType.string;
                        }
                    }
                }
            }
        }
        const compatibleTypes = [];
        for (let i = 0; i < types.length; i++) {
            let compatible = (types[i] | ColumnType.string);
            if (integers[i]) {
                compatible |= ColumnType.integer;
            }
            compatibleTypes.push(compatible);
        }
        this._core.log.write(LogLevel.info, `compatible types ${Math.round(window.performance.now() - start)}ms`);
        return compatibleTypes;
    }
    inferTypes(data, firstRow = 0, maxRows = Number.MAX_VALUE) {
        const columnTypes = [];
        const compatibleTypes = this.compatibleTypes(data, firstRow, maxRows);
        for (let i = 0; i < compatibleTypes.length; i++) {
            let columnType;
            const compatibleType = compatibleTypes[i];
            if (compatibleType & ColumnType.integer) {
                columnType = ColumnType.integer;
            }
            else if (compatibleType & ColumnType.float) {
                columnType = ColumnType.float;
            }
            else if (compatibleType & ColumnType.date) {
                columnType = ColumnType.date;
            }
            else {
                columnType = ColumnType.string;
            }
            columnTypes.push(columnType);
        }
        return columnTypes;
    }
    convertToObject(table) {
        const headings = table.headings;
        const jsonObject = [];
        for (let i = 0; i < table.all.ids.length; i++) {
            const row = {};
            for (let j = 0; j < headings.length; j++) {
                const column = headings[j];
                const value = table.all.columnValues(j)[i];
                switch (table.getColumnType(j)) {
                    case ColumnType.integer:
                    case ColumnType.float:
                        row[column] = value;
                        break;
                    case ColumnType.string:
                    case ColumnType.date:
                    default:
                        row[column] = table.data[i][j];
                        break;
                }
                jsonObject.push(row);
            }
        }
        return jsonObject;
    }
}
