import { vec3 } from "gl-matrix";
import { Constants } from "../constants.js";
export class VectorHelper {
    static orthonormalBasis(n, b1, b2) {
        if (n[0] > 0.9) {
            vec3.copy(b1, Constants.VECTOR3_UNITY);
        }
        else {
            vec3.copy(b1, Constants.VECTOR3_UNITX);
        }
        vec3.scaleAndAdd(b1, b1, n, -vec3.dot(b1, n));
        vec3.normalize(b1, b1);
        vec3.cross(b2, n, b1);
    }
}
