import { ensureSearchExpressionGroupArray } from './group';
export function narrow(a, b) {
    if (!a) {
        return b;
    }
    const arrs = [a, b].map(ensureSearchExpressionGroupArray);
    const [arrA, arrB] = arrs;
    arrB[0].clause = '&&';
    return arrA.concat(arrB);
}
