import { ColorScaleNone, SignalNames } from './constants';
import { safeFieldName } from './expr';
export function linearScale(scaleName, domain, range, reverse, zero, nice = true) {
    const scale = {
        name: scaleName,
        type: 'linear',
        range,
        round: true,
        reverse,
        domain,
        zero,
        nice,
    };
    return scale;
}
export function pointScale(scaleName, data, range, field, reverse) {
    const scale = {
        name: scaleName,
        type: 'point',
        range,
        domain: {
            data,
            field: safeFieldName(field),
            sort: true,
        },
        padding: 0.5,
    };
    if (reverse !== undefined) {
        scale.reverse = reverse;
    }
    return scale;
}
export function binnableColorScale(scaleName, colorBin, data, field, scheme) {
    scheme = scheme || ColorScaleNone;
    const domain = {
        data,
        field: safeFieldName(field),
    };
    const range = {
        scheme,
    };
    const reverse = { signal: SignalNames.ColorReverse };
    if (colorBin !== 'continuous') {
        range.count = { signal: SignalNames.ColorBinCount };
    }
    switch (colorBin) {
        case 'continuous': {
            const sequentialScale = {
                name: scaleName,
                type: 'linear',
                domain,
                range,
                reverse,
            };
            return sequentialScale;
        }
        case 'quantile': {
            const quantileScale = {
                name: scaleName,
                type: 'quantile',
                domain,
                range,
                reverse,
            };
            return quantileScale;
        }
        default: {
            const quantizeScale = {
                name: scaleName,
                type: 'quantize',
                domain,
                range,
                reverse,
            };
            return quantizeScale;
        }
    }
}
