import { vec3 } from "gl-matrix";
import { Cube } from "../meshes/cube.js";
export class BoundsHelper {
    static rotateBounds(minBounds, maxBounds, rotation, rotatedMinBounds, rotatedMaxBounds, offset) {
        const sizeX = maxBounds[0] - minBounds[0];
        const sizeY = maxBounds[1] - minBounds[1];
        const sizeZ = maxBounds[2] - minBounds[2];
        const min = rotatedMinBounds;
        const max = rotatedMaxBounds;
        vec3.set(min, Number.MAX_VALUE, Number.MAX_VALUE, Number.MAX_VALUE);
        vec3.set(max, -Number.MAX_VALUE, -Number.MAX_VALUE, -Number.MAX_VALUE);
        const vertices = Cube.POSITIONS;
        const position = vec3.create();
        for (let i = 0; i < 8; i++) {
            vec3.set(position, vertices[i * 3] * sizeX, vertices[i * 3 + 1] * sizeY, vertices[i * 3 + 2] * sizeZ);
            vec3.add(position, position, offset);
            vec3.transformQuat(position, position, rotation);
            vec3.subtract(position, position, offset);
            vec3.min(min, min, position);
            vec3.max(max, max, position);
        }
        vec3.add(position, minBounds, maxBounds);
        vec3.scale(position, position, 0.5);
        vec3.add(min, min, position);
        vec3.add(max, max, position);
    }
    static cylinder(pa, pb, radius, minBounds, maxBounds) {
        const a = vec3.create();
        vec3.subtract(a, pb, pa);
        const aa = vec3.dot(a, a);
        const ex = radius * Math.sqrt(1 - a[0] * a[0] / aa);
        const ey = radius * Math.sqrt(1 - a[1] * a[1] / aa);
        const ez = radius * Math.sqrt(1 - a[2] * a[2] / aa);
        minBounds[0] = Math.min(pa[0] - ex, pb[0] - ex);
        minBounds[1] = Math.min(pa[1] - ey, pb[1] - ey);
        minBounds[2] = Math.min(pa[2] - ez, pb[2] - ez);
        maxBounds[0] = Math.max(pa[0] + ex, pb[0] + ex);
        maxBounds[1] = Math.max(pa[1] + ey, pb[1] + ey);
        maxBounds[2] = Math.max(pa[2] + ez, pb[2] + ez);
    }
}
