import { vec3 } from "gl-matrix";
export class Manipulator {
    constructor() {
        this.pickedIndex = 0;
        this.maxTranslationSquared = 0;
        this.initialPosition = vec3.create();
        this.position = vec3.create();
        this.previousPosition = vec3.create();
        this.holdOrigin = vec3.create();
        this.positionRelativeToCentroid = vec3.create();
        this.previousPositionRelativeToCentroid = vec3.create();
        this.rotationAxis = vec3.create();
        this.previousRotationAxis = vec3.create();
    }
}
